var e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Blok config dan makro Klipper siap tempel - urutan start, penanganan filamen, input shaping, bed mesh, dan lainnya. Salin salah satu lalu masukkan ke printer.cfg Anda (Config Editor adalah tempat yang baik untuk menempelkannya).`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Bantuan`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Tentang Config Templates`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Tutup`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Cara memakai`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Filter berdasarkan kategori untuk menemukan makro atau blok config.`}},{t:0,b:{t:2,i:[{t:3}],s:`Baca deskripsinya dan bagian apa saja yang diperlukan.`}},{t:0,b:{t:2,i:[{t:3}],s:`Salin template, tempelkan ke config Anda, lalu sesuaikan nilainya.`}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:`Apa ini`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Kumpulan blok bangunan Klipper umum yang terkurasi: gcode_macros (PRINT_START, PAUSE/RESUME, load/unload filamen, M600) dan bagian config ([input_shaper], [bed_mesh], [firmware_retraction], …). Ini hanya titik awal - baca masing-masing dan setel untuk mesin Anda.`}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:`Menyisipkan template`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Salin sebuah template, lalu tempelkan ke printer.cfg Anda - tampilan Raw di Config Editor adalah tempat yang praktis. Setelah menyimpan, restart firmware akan menerapkannya. Selalu tinjau nilainya terlebih dahulu; default di sini masuk akal tetapi belum disetel untuk printer Anda.`}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`Bagian yang diperlukan`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Setiap template mencantumkan bagian config yang didefinisikan atau dibutuhkannya. Jika sebuah bagian sudah ada di config Anda, gabungkan kuncinya alih-alih menempel duplikat (bagian duplikat akan ditolak saat startup).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glosarium`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:`Template`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Cuplikan config Klipper atau makro G-code siap tempel yang Anda salin ke printer.cfg.`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`gcode_macro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Perintah bernama yang Anda definisikan di config (mis. PRINT_START) yang menjalankan urutan G-code.`}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:`Bagian`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Blok config [dalam kurung], mis. [bed_mesh] - unit pengelompokan konfigurasi Klipper.`}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:`Kategori`}},all:{t:0,b:{t:2,i:[{t:3}],s:`Semua kategori`}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:`Salin`}},copied:{t:0,b:{t:2,i:[{t:3}],s:`Tersalin!`}},requires:{t:0,b:{t:2,i:[{t:3,v:`Bagian: `},{t:4,k:`sections`}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` template`}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Memuat template…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Tidak dapat memuat template.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Tidak ada template di kategori ini.`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`Coba lagi`}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:`Blok config`}},macros:{t:0,b:{t:2,i:[{t:3}],s:`Makro`}}}}};export{e as default};